{
  "selections": [
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data", "/situations/2"],
      "relevance": "내담자가 '제 자식인데'라며 아내의 일방적 결정에 배제감을 느끼는 것은, 자신이 가족 내에서 특별한 결정권자여야 한다는 특권의식·과대성 스키마와 직접 연결됨. 성장 배경에서 어머니가 '너는 급이 다르다'며 모든 문제를 무마해 준 경험이 이 스키마의 근원이며, 상황 사례2에서 아내의 별거 통보에 장모에게 전화해 따진 행동도 같은 패턴."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "'제 자식인데 말 한마디 없이 혼자 결정한 거잖아요'라는 발화는, 자신이 특별한 사람이므로 자녀에 관한 중요한 결정은 반드시 자신을 경유해야 한다는 핵심 신념을 반영함. 성장 배경에서 규칙·절차가 자신에게 적용되지 않았던 경험이 이 신념을 강화함."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/situations/2"],
      "relevance": "아내가 자신을 배제하고 결정을 내린 것을 '참을 수 없는 일'로 느끼는 것은, 타인이 자신에게 이래라저래라 하거나 자신의 영역을 침범하는 것을 용납할 수 없다는 태도와 연결됨. 상황 사례2에서 장모에게 '제가 뭘 그렇게 잘못했습니까'라고 따진 행동도 같은 태도의 발현."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": [],
      "relevance": "아내의 일방적 결정에 대한 강한 배제감은, 자신이 보통 사람처럼 통보만 받는 존재로 취급되면 특별할 것 없는 사람이 된다는 부정적 가정에서 비롯된 것으로 해석 가능."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/2"],
      "relevance": "내담자가 아내의 말('들러리였어') 자체보다 '애까지 데리고 나간' 행동을 문제로 삼는 것은, 관계 문제의 원인을 자신의 언행이 아닌 상대의 행동(일방적 결정)에서 찾는 외현화 전략과 일치함. 상황 사례2에서도 아내의 말보다 장모에게 따지는 행동으로 반응함."
    }
  ]
}

